using System.Runtime.CompilerServices;
using System.Text.Json;
using Strands.Agents.MultiAgent;

namespace Strands.Agents.Tests.MultiAgent;

// Captured CPython 3.10.2 JSON-float repr oracles; no private numeric helper is invoked.
public sealed class SwarmPythonBinary64EdgeTests
{
    private static readonly IReadOnlyDictionary<string, Case> Cases = new Dictionary<string, Case>(StringComparer.Ordinal)
    {
        ["EXACT-HALF-SUB-EVEN-ZERO"] = new("0.", "0.0"),
        ["ABOVE-EXACT-HALF-SUB"] = new("0.", "5e-324"),
        ["NEGATIVE-EXACT-HALF-SUB"] = new("-0.", "-0.0"),
        ["EXACT-NORMAL-BOUNDARY-EVEN"] = new("0.", "2.2250738585072014e-308"),
        ["BELOW-NORMAL-BOUNDARY"] = new("0.", "2.225073858507201e-308"),
        ["ABOVE-NORMAL-BOUNDARY"] = new("0.", "2.2250738585072014e-308"),
        ["ODD-LOWER-UNIT-MIDPOINT"] = new("1.00000000000000033306690738754696212708950042724609375", "1.0000000000000004"),
        ["NEGATIVE-ODD-LOWER-MIDPOINT"] = new("-1.00000000000000033306690738754696212708950042724609375", "-1.0000000000000004"),
        ["BELOW-OVERFLOW-MIDPOINT"] = new(".0", "1.7976931348623157e+308"),
        ["EXACT-OVERFLOW-MIDPOINT"] = new(".0", "inf"),
        ["ABOVE-OVERFLOW-MIDPOINT"] = new(".0", "inf"),
        ["LARGE-COEFFICIENT-EXPONENT-CANCELLATION"] = new(".0e-4096", "1.0"),
        ["LARGE-FRACTION-EXPONENT-CANCELLATION"] = new("0.", "1.0"),
        ["LEADING-ZERO-EXPONENT"] = new("1e-", "0.0"),
        ["BELOW-UNIT-MIDPOINT-DISTANT-LAST-DIGIT"] = new("1.", "1.0"),
        ["ABOVE-UNIT-MIDPOINT-DISTANT-LAST-DIGIT"] = new("1.", "1.0000000000000002"),
    };

    [Theory]
    [InlineData("EXACT-HALF-SUB-EVEN-ZERO")]
    [InlineData("ABOVE-EXACT-HALF-SUB")]
    [InlineData("NEGATIVE-EXACT-HALF-SUB")]
    [InlineData("EXACT-NORMAL-BOUNDARY-EVEN")]
    [InlineData("BELOW-NORMAL-BOUNDARY")]
    [InlineData("ABOVE-NORMAL-BOUNDARY")]
    [InlineData("ODD-LOWER-UNIT-MIDPOINT")]
    [InlineData("NEGATIVE-ODD-LOWER-MIDPOINT")]
    [InlineData("BELOW-OVERFLOW-MIDPOINT")]
    [InlineData("EXACT-OVERFLOW-MIDPOINT")]
    [InlineData("ABOVE-OVERFLOW-MIDPOINT")]
    [InlineData("LARGE-COEFFICIENT-EXPONENT-CANCELLATION")]
    [InlineData("LARGE-FRACTION-EXPONENT-CANCELLATION")]
    [InlineData("LEADING-ZERO-EXPONENT")]
    [InlineData("BELOW-UNIT-MIDPOINT-DISTANT-LAST-DIGIT")]
    [InlineData("ABOVE-UNIT-MIDPOINT-DISTANT-LAST-DIGIT")]
    public async Task PythonKnowledgeMatchesCapturedBinary64BoundaryReference(string id)
    {
        var selected = Cases[id];
        var model = new CaptureModel();
        await using var agent = new Agent(new() { Id = "reader", Model = model });
        var swarm = new Swarm(SwarmOptions.Python with { Nodes = [new(agent)], ContextTextProfile = SwarmContextTextProfile.PythonRepr });
        using (var document = JsonDocument.Parse(selected.RawJson))
            swarm.SharedContext.AddContext("memory", "value", document.RootElement);

        var result = await swarm.InvokeAsync("task");

        Assert.Equal(Status.Completed, result.Status);
        var stored = swarm.SharedContext.GetAll()["memory"]["value"];
        Assert.Equal(JsonValueKind.Number, stored.ValueKind);
        Assert.Equal(selected.RawJson, stored.GetRawText());
        var input = Assert.Single(Assert.Single(model.Requests).Messages, message => message.Role == Role.User);
        var line = Assert.Single(input.Text.Split('\n'), value => value.StartsWith("\u2022 memory: ", StringComparison.Ordinal));
        Assert.Equal("\u2022 memory: {'value': " + selected.PythonRepr + "}", line);
    }

    private sealed record Case(string RawJson, string PythonRepr);

    private sealed class CaptureModel : IModel
    {
        internal List<ModelRequest> Requests { get; } = [];
        public async IAsyncEnumerable<ModelStreamEvent> StreamAsync(ModelRequest request,
            [EnumeratorCancellation] CancellationToken cancellationToken = default)
        {
            cancellationToken.ThrowIfCancellationRequested();
            Requests.Add(request);
            if (Requests.Count != 1) throw new InvalidOperationException("A completed single-node visit must not be replayed.");
            yield return new ModelMessageStartEvent();
            yield return new ModelContentBlockStartEvent(0);
            yield return new ModelContentBlockDeltaEvent(0, Text: "done");
            yield return new ModelContentBlockStopEvent(0);
            yield return new ModelMessageStopEvent(StopReasons.EndTurn);
            await Task.CompletedTask;
        }
    }
}
